class ResourcePreloader{constructor(){this.preloadedResources=new Set,this.criticalFonts=[],this.criticalImages=["../assets/default-pet-profile.jpg","../assets/default-user-profile.jpg"]}preloadCriticalResources(){this.criticalImages.forEach(e=>{this.preloadImage(e)}),this.prefetchCriticalData()}preloadImage(e){if(this.preloadedResources.has(e))return;const t=document.createElement("link");t.rel="preload",t.as="image",t.href=e,document.head.appendChild(t),this.preloadedResources.add(e)}preloadScript(e,t=!1){if(this.preloadedResources.has(e))return;const a=document.createElement("link");a.rel="modulepreload",a.href=e,document.head.appendChild(a),this.preloadedResources.add(e)}prefetchNavigation(){["../pets/pets.html","../login/login.html","../signup/signup.html"].forEach(e=>{const t=document.createElement("link");t.rel="prefetch",t.href=e,document.head.appendChild(t)})}prefetchCriticalData(){const e=window.location.pathname;(e.includes("home")||e.includes("index"))&&(this.prefetchAPI("/api/pets/featured"),this.prefetchAPI("/api/testimonials"))}prefetchAPI(e){const t=window.APP_CONFIG?.api?.baseURL||"http://localhost:8080";fetch(t+e,{method:"GET",headers:{"Cache-Control":"max-age=300"}}).catch(()=>{})}loadNonCriticalResources(){requestIdleCallback(()=>{this.prefetchNavigation()})}init(){this.preloadCriticalResources(),"complete"===document.readyState?this.loadNonCriticalResources():window.addEventListener("load",()=>{this.loadNonCriticalResources()})}}if("undefined"!=typeof window){window.ResourcePreloader=ResourcePreloader;(new ResourcePreloader).init()}"undefined"!=typeof module&&module.exports&&(module.exports=ResourcePreloader);